284	// error: a user Ctrl+C exits quietly (SilentError, so main.go doesn't reprint
285	// it), while a real deadline reports the timeout.
286	func classifyWaitContextErr(err error) error {
287		if errors.Is(err, context.Canceled) {
288			return NewSilentError(err)
289		}
290		return fmt.Errorf("timed out waiting for initial clone: %w", err)
291	}
