293	// explainSuspendedMirror tells the user a suspended placement can't be served
294	// and to contact support. Suspension usually follows a loss of upstream GitHub
295	// access (App uninstalled, repo went private, or a transient API error); the
296	// fix is operator-side, so we point at support rather than leaking an internal
297	// admin command.
298	func explainSuspendedMirror(w io.Writer, mirrorID string) {
299		fmt.Fprintf(w,
300			"\nMirror %s is registered but suspended, so it can't be cloned yet.\n"+
301				"This usually means upstream GitHub access was lost (App uninstalled,\n"+
302				"the repo went private, or a transient API error). Contact support to\n"+
303				"restore it.\n",
304			mirrorID)
305	}
