// request ID to poll and, for an absolute Location, the server URL to poll it
// on (nil when the Location is relative and the submit client should be kept).
func mirrorRequestPollTarget(location string) (*url.URL, uuid.UUID, error) {
	if strings.TrimSpace(location) == "" {
		return nil, uuid.Nil, errors.New("mirror request response is missing Location")
